    <div class="nav-links"><a href="/">Home</a><a href="{{ route('public.products.opsbridge') }}" class="{{ request()->routeIs('public.products.opsbridge')?'active':'' }}">OpsBridge</a><a href="{{ route('public.products.erp') }}" class="{{ request()->routeIs('public.products.erp')?'active':'' }}">Niyantron ERP</a><a href="/about">About</a><a href="/contact">Contact</a></div>
